def calculate(s: str) -> int:
    num = 0
    ope = '+'
    stack = []
    i = 0

    while i < len(s):
        if s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1
            continue

        if i >= len(s) or s[i] in '+-*/':
            if ope == '+':
                stack.append(num)
            elif ope == '-':
                stack.append(-num)
            elif ope == '*':
                stack.append(stack.pop() * num)
            elif ope == '/':
                stack.append(int(stack.pop() / num))

            if i < len(s):
                ope = s[i]
                num = 0

            i += 1

    result = sum(stack)
    return result
